pre-actions.script:
if (typeof tokenRoute === 'undefined' || !tokenRoute || !tokenRoute.basePath) { sri.sendRedirectAndStopRender('/'); return }
const quasarLangs = ['en-US', 'de', 'es', 'fr', 'it', 'pt-BR', 'ja', 'zh-CN', 'ru', 'nl']
const localeTag = String(ec.user.locale || 'en_US').replace('_', '-')
const language = localeTag.split('-')[0]
const quasarLang = quasarLangs.includes(localeTag) ? localeTag : quasarLangs.find((tag) => tag.split('-')[0] === language) || 'en-US'
// the build with the template compiler: a public screen may be a server-merged qvt or a .qvue
footer_scripts.add('/libs/vue/vue.global.prod.js')
footer_scripts.add('/libs/quasar/quasar.umd.prod.js')
footer_scripts.add('/libs/quasar/lang/' + quasarLang + '.umd.prod.js')
if (sri.getThemeValues('STRT_STYLESHEET').some((sheet) => String(sheet).includes('/libs/material-symbols/')))
    footer_scripts.add('/libs/quasar/icon-set/material-symbols-outlined.umd.prod.js')
footer_scripts.add('/js/MoquiLib.js')
footer_scripts.add('/js/MoquiL10n.js')
// a call link's guest page (/call/<token>, basic-comms): the call client and m-call-guest, registered before the components
if (tokenRoute.name === 'call') footer_scripts.add('/js/WebrootCall.js')
if (tokenRoute.name === 'call') footer_scripts.add('/js/WebrootCall.render.js')
footer_scripts.add('/js/WebrootVue.qvt.render.js')
// loaded for its components: it mounts nothing on a page without the moqui-config block
footer_scripts.add('/js/WebrootVue.qvt.js')
footer_scripts.add('/js/WebrootPublic.qvt.js')
let quasarConfig = null
for (const text of sri.getThemeValues('STRT_QUASAR_CONFIG')) {
    try { quasarConfig = Object.assign(quasarConfig || {}, JSON.parse(text)) } catch (e) { ec.logger.error('Theme STRT_QUASAR_CONFIG is not JSON: ' + e) }
}
const context = tokenRoute.context || {}
html_title = tokenRoute.title || context.name || ec.l10n.localize('Shared')
const logoList = sri.getThemeValues('STRT_HEADER_LOGO')
publicConfig = {
    sessionToken: ec.web.sessionToken, appHost: ec.web.getHostName(true), appRootPath: '', locale: localeTag, timeZone: ec.user.timeZone,
    quasarLang: quasarLang.replace(/-([a-zA-Z])/g, (m, ch) => ch.toUpperCase()), quasar: quasarConfig,
    qvt: { build: 'compiler', handles: ['merged-fragment', 'static-template'] },
    route: { name: tokenRoute.name, basePath: tokenRoute.basePath, title: tokenRoute.title || null,
        renderModes: Array.from(tokenRoute.renderModes || []) },
    context: context,
    shell: { logoUrl: logoList.length ? sri.buildUrl(logoList[0]).url : '' },
    labels: { loading: ec.l10n.localize('Loading'), notFound: ec.l10n.localize('This link has expired or was not found.') }
}
